# Get detailed information about the main electrical panels including their locations
panel_guids = []
main_panels = []

# Find the main electrical panels from our previous search
all_elements = ifc_file.by_type("IfcElement")
for element in all_elements:
    if hasattr(element, 'Name') and element.Name:
        name_lower = element.Name.lower()
        if 'panelboard' in name_lower and ('unit a' in name_lower or 'unit b' in name_lower):
            main_panels.append(element)
            panel_guids.append(element.GlobalId)

print(f"Found {len(main_panels)} main electrical panels:")

# Get detailed information for each panel including location
for panel in main_panels:
    print(f"\n--- Panel: {panel.Name} ---")
    print(f"Type: {panel.is_a()}")
    print(f"GUID: {panel.GlobalId}")

    # Try to find the spatial container (room/space) where this panel is located
    spatial_container = None

    # Look for IfcRelContainedInSpatialStructure relationships
    for rel in ifc_file.by_type("IfcRelContainedInSpatialStructure"):
        if panel in rel.RelatedElements:
            spatial_container = rel.RelatingStructure
            break

    if spatial_container:
        container_name = spatial_container.Name if hasattr(spatial_container, 'Name') and spatial_container.Name else "Unnamed"
        print(f"Located in: {container_name} ({spatial_container.is_a()})")
    else:
        print("Spatial container: Not found in IfcRelContainedInSpatialStructure")

        # Try alternative method - look for IfcRelSpaceBoundary
        for rel in ifc_file.by_type("IfcRelSpaceBoundary"):
            if hasattr(rel, 'RelatedBuildingElement') and rel.RelatedBuildingElement == panel:
                space = rel.RelatingSpace
                space_name = space.Name if hasattr(space, 'Name') and space.Name else "Unnamed"
                print(f"Adjacent to space: {space_name} ({space.is_a()})")
                break

    # Try to get coordinates if available
    try:
        if hasattr(panel, 'ObjectPlacement') and panel.ObjectPlacement:
            placement = panel.ObjectPlacement
            if hasattr(placement, 'RelativePlacement'):
                rel_placement = placement.RelativePlacement
                if hasattr(rel_placement, 'Location') and rel_placement.Location:
                    coords = rel_placement.Location.Coordinates
                    print(f"Coordinates: ({coords[0]:.2f}, {coords[1]:.2f}, {coords[2]:.2f})")
    except:
        print("Coordinates: Not available")

# Also check if there are any other electrical panels we might have missed
print(f"\n--- Other electrical equipment ---")
other_electrical = []
for element in all_elements:
    if hasattr(element, 'Name') and element.Name:
        name_lower = element.Name.lower()
        if any(keyword in name_lower for keyword in ['fire alarm panel', 'service', 'main breaker']) and element not in main_panels:
            other_electrical.append(element)

for equipment in other_electrical:
    print(f"- {equipment.Name} ({equipment.is_a()})")

    # Get location info for other electrical equipment too
    for rel in ifc_file.by_type("IfcRelContainedInSpatialStructure"):
        if equipment in rel.RelatedElements:
            container = rel.RelatingStructure
            container_name = container.Name if hasattr(container, 'Name') and container.Name else "Unnamed"
            print(f"  Located in: {container_name}")
            break
